const topicItems = $('合并请求结果').all();
const answerItems = $('无关闲聊').all();

const topic = topicItems?.[0]?.json?.topic || {};
const answer = answerItems?.[0]?.json?.text || '';

return [
  {
    json: {
      answer,
      topic_id: topic.topic_id || null,
    },
  },
];

const items = $input.all();

const PRODUCT_GROUPS = [
  {
    keyword: '对焊管件',
    aliases: ['锻制对焊管件', '对焊管件', '对焊件', 'butt weld fitting'],
  },
  {
    keyword: '高压管件',
    aliases: ['高压管件', '锻制管件', '承插管件', 'high pressure fitting'],
  },
  {
    keyword: '低压管件',
    aliases: ['低压管件', '铸造管件', '铸件管件', 'low pressure fitting'],
  },
  {
    keyword: '无缝管',
    aliases: [
      '无缝换热管',
      '无缝仪表管',
      '无缝钢管',
      '无缝管道',
      'seamless pipe',
      'seamless tube',
      'smls pipe',
      'smls tube',
      '无缝管',
    ],
  },
  {
    keyword: '焊管',
    aliases: [
      '焊接换热管',
      '焊接仪表管',
      '焊接钢管',
      '焊接管道',
      'welded pipe',
      'welded tube',
      '焊管',
    ],
  },
  {
    keyword: '不锈钢板',
    aliases: ['不锈钢板', '板卷', '卷板', '钢板', '板材', 'plate'],
  },
  {
    keyword: '不锈钢棒材',
    aliases: ['不锈钢棒材', '棒材', '圆钢', 'bar'],
  },
  {
    keyword: '线材',
    aliases: ['不锈钢线材', 'wire rod', '线材', '盘条', 'wire'],
  },
  {
    keyword: '法兰',
    aliases: ['法兰盘', 'flange', '法兰'],
  },
  {
    keyword: '管件',
    aliases: ['管件', 'fitting'],
  },
];

function text(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .trim()
    .replace(/^[\s“”‘’'"`]+|[\s“”‘’'"`，。；;！？!?]+$/g, '');
}

/**
 * n8n 的部分 Code 节点沙箱未暴露 structuredClone。
 * 当前输入来自 n8n item.json，属于 JSON 数据，因此使用 JSON 深拷贝即可。
 */
function cloneJson(value) {
  if (value === null || value === undefined) {
    return {};
  }

  return JSON.parse(JSON.stringify(value));
}

function extractStandard(value) {
  const source = text(value).toUpperCase();

  const patterns = [
    // ASTM A213、ASME B16.5、ANSI B16.5
    /\b(?:ASTM|ASME|ANSI)\s+((?:S[AB]|A|B)\s*[-_ ]?\s*\d{2,4}(?:M)?(?:\s*[\/_]\s*(?:S[AB]|A|B)?\s*[- ]?\s*\d{2,4}M?)?(?:\.\d+)?)\b/i,

    // A213、SA-213、SA-213/SA-213M、B16.5
    /\b((?:S[AB]|A|B)\s*[-_ ]?\s*\d{2,4}(?:M)?(?:\s*[\/_]\s*(?:S[AB]|A|B)?\s*[- ]?\s*\d{2,4}M?)?(?:\.\d+)?)\b/i,

    // ISO、EN、DIN、JIS、API、GB/T 等标准
    /\b((?:ISO|EN|DIN|JIS|API|GB(?:\/T)?|HG(?:\/T)?|SH(?:\/T)?|NB(?:\/T)?)\s*[- ]?\s*\d{2,6}(?:[.\-]\d+)*(?:\s*[-:]\s*\d{2,4})?)\b/i,
  ];

  for (const pattern of patterns) {
    const match = source.match(pattern);

    if (match) {
      return match[1]
        .replace(/\s+/g, '')
        .replace(/_/g, '/');
    }
  }

  return '';
}

function findKnownProduct(value) {
  const source = text(value).toLowerCase();
  let best = null;

  for (const group of PRODUCT_GROUPS) {
    for (const alias of group.aliases) {
      const normalizedAlias = alias.toLowerCase();

      if (!source.includes(normalizedAlias)) {
        continue;
      }

      // 优先选择最长别名，避免“对焊管件”被较短的“管件”覆盖。
      if (!best || normalizedAlias.length > best.alias.length) {
        best = {
          alias: normalizedAlias,
          keyword: group.keyword,
        };
      }
    }
  }

  return best ? best.keyword : '';
}

function cleanProduct(value) {
  const result = text(value)
    .replace(/^(?:关于|有关|查询|查找|请查询|请查找|了解)\s*/u, '')
    .replace(
      /(?:的)?(?:相关)?(?:执行|采用|适用|对应|产品)?标准(?:是什么|有哪些|有哪几种|列表)?$/u,
      '',
    )
    .replace(
      /(?:的)?(?:使用场景|应用场景|适用场景|适用范围|适用产品|相关产品|使用产品|上下文|相关文档|文档|资料)(?:是什么|有哪些|吗)?$/u,
      '',
    )
    .replace(/(?:是什么|有哪些|有哪几种|吗|呢)$/u, '')
    .trim();

  return result || text(value);
}

function cleanStandardFallback(value) {
  return text(value)
    .replace(
      /^(?:关于|有关|查询|查找|请查询|请查找|ASTM\s*)/iu,
      '',
    )
    .replace(/(?:标准|规范)(?:的)?/gu, '')
    .replace(
      /(?:适用产品|相关产品|使用产品|使用场景|应用场景|适用范围|上下文|相关文档|文档|资料)(?:是什么|有哪些|吗)?$/u,
      '',
    )
    .replace(/(?:是什么|有哪些|有哪几种|吗|呢)$/u, '')
    .trim();
}

const output = [];
const seen = new Set();

for (let index = 0; index < items.length; index += 1) {
  const original = items[index].json ?? {};
  const item = cloneJson(original);

  item.method =
    item.method &&
    typeof item.method === 'object' &&
    !Array.isArray(item.method)
      ? item.method
      : {};

  item.method.params =
    item.method.params &&
    typeof item.method.params === 'object' &&
    !Array.isArray(item.method.params)
      ? item.method.params
      : {};

  // 兼容模型偶尔输出正确拼写，但现有工作流仍使用 hybid_search。
  if (item.method.type === 'hybrid_search') {
    item.method.type = 'hybid_search';
  }

  const originalKeyword = text(item.keyword);
  let applied = 'none';

  if (item.method.type === 'document_direct') {
    item.keyword = originalKeyword;
    item.entity_type = 'none';
    item.method.params.port = '';
    applied = 'document-direct';
  } else if (item.method.type === 'kg_search') {
    const standard = extractStandard(originalKeyword);
    const product = findKnownProduct(originalKeyword);
    const hint = String(item.entity_type ?? '').toLowerCase();
    const currentPort = String(item.method.params.port ?? '');

    /*
     * 判定优先级：
     * 1. 标准代号正则
     * 2. 已知产品别名
     * 3. 模型提供的实体类型
     * 4. 模型提供的端口
     * 5. 无法确定时降级到混合检索
     */
    if (standard) {
      item.keyword = standard;
      item.entity_type = 'standard';
      item.method.params.port = 'standard-context';
      applied = 'standard-pattern';
    } else if (product) {
      item.keyword = product;
      item.entity_type = 'product';
      item.method.params.port = 'product-standards';
      applied = 'product-alias';
    } else if (
      hint === 'standard' ||
      currentPort === 'standard-context'
    ) {
      item.keyword = cleanStandardFallback(originalKeyword);
      item.entity_type = 'standard';
      item.method.params.port = 'standard-context';
      applied = 'standard-hint';
    } else if (
      hint === 'product' ||
      currentPort === 'product-standards'
    ) {
      item.keyword = cleanProduct(originalKeyword);
      item.entity_type = 'product';
      item.method.params.port = 'product-standards';
      applied = 'product-hint';
    } else {
      item.keyword = originalKeyword;
      item.entity_type = 'none';
      item.method.type = 'hybid_search';
      item.method.params.port = '';
      applied = 'ambiguous-to-hybrid';
    }
  } else {
    item.keyword = originalKeyword;
    item.entity_type = 'none';
    item.method.params.port = '';
  }

  if (!item.keyword) {
    continue;
  }

  const dedupeKey = [
    item.method.type,
    item.method.params.port,
    String(item.keyword).toLowerCase(),
  ].join('|');

  if (seen.has(dedupeKey)) {
    continue;
  }

  seen.add(dedupeKey);

  item.route_guard = {
    applied,
    original_keyword: originalKeyword,
    keyword_changed: originalKeyword !== item.keyword,
    port_forced: item.method.type === 'kg_search',
  };

  output.push({
    json: item,
    pairedItem: {
      item: index,
    },
  });
}

return output;

