const base = $('合并item并去重').first().json || {};
const raw = $json.text ?? $json.output ?? $json.response ?? '';
let decision;
try {
  decision = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch {
  decision = null;
}
const originalItems = Array.isArray(base.retrieval_items) ? base.retrieval_items : [];
const validIds = new Set(originalItems.map((item) => String(item.chunk_id || '')));
const requestedIds = Array.isArray(decision?.keep_chunk_ids) ? decision.keep_chunk_ids.map((id) => String(id)) : null;
const isValid = requestedIds !== null && requestedIds.every((id) => validIds.has(id));
if (!isValid) {
  return [{ json: { ...base, relevance_filter: { applied: false, fallback: true, reason: 'invalid_model_output' } } }];
}
const keepIds = new Set(requestedIds);
const keptItems = originalItems.filter((item) => keepIds.has(String(item.chunk_id || '')));
const contexts = base.retrieval_context_by_chunk_id || {};
const marker = '\n\n\u3010\u53ec\u56de\u9879 ';
const prompt = String(base.prompt_text || '');
const markerIndex = prompt.indexOf(marker);
const preamble = (markerIndex >= 0 ? prompt.slice(0, markerIndex) : prompt).trimEnd();
const retrievalContext = keptItems.map((item) => contexts[item.chunk_id]).filter(Boolean).join('\n\n---\n\n');
return [{
  json: {
    ...base,
    retrieval_items: keptItems,
    prompt_text: preamble + '\n\n' + (retrievalContext || '\u6ca1\u6709\u53ef\u7528\u7684\u53ec\u56de\u7ed3\u679c\u3002'),
    relevance_filter: { applied: true, fallback: false, input_count: originalItems.length, output_count: keptItems.length, reason: String(decision.reason || '') },
  },
}];

const topicItems = $('合并请求结果').all();
const answerItems = $('final_qa_agent').all();
const context = $('合并item并去重').first().json || {};
const allowedReferences = new Set((context.retrieval_items || [])
  .filter((item) => item && item.citation_allowed === true && item.file_path)
  .map((item) => String(item.file_path).trim()));

const topic = topicItems?.[0]?.json?.topic || {};
let answer = String(answerItems?.[0]?.json?.output || answerItems?.[0]?.json?.text || '');
const seenReferences = new Set();
answer = answer.replace(/<reference>([\s\S]*?)<\/reference>/gi, (full, rawPath) => {
  const path = String(rawPath || '').trim();
  if (!allowedReferences.has(path) || seenReferences.has(path)) return '';
  seenReferences.add(path);
  return '<reference>' + path + '</reference>';
});
answer = answer.replace(/\n{3,}/g, '\n\n').trim();

return [{
  json: {
    answer,
    topic_id: topic.topic_id || null,
  },
}];
